OutputTag<Event> lateTag = new OutputTag<Event>("late-events"){};

SingleOutputStreamOperator<Result> main = events
    .keyBy(Event::getAccountId)
    .window(TumblingEventTimeWindows.of(Time.minutes(1)))
    .allowedLateness(Time.seconds(30))
    .sideOutputLateData(lateTag)
    .aggregate(new TransactionCountAggregate());

// Events later than watermark + allowedLateness go here
DataStream<Event> lateEvents = main.getSideOutput(lateTag);
lateEvents.sinkTo(deadLetterSink);  // reconcile in batch later
